import Foundation

/// The response from an agent interaction, including generated content and any tool execution results.
public struct AgentResponse {
    /// The text content generated by the language model.
    public let content: String
    /// Optional results from tool executions during the interaction.
    public let toolResults: [ToolResult]?
}

/// The main agent class that orchestrates interactions with language models and tools.
public final class Agent {
    private let provider: LanguageModelProvider
    private let tools: [Tool]
    private let instructions: String
    private var context: AgentContext

    /// Initializes a new agent with the specified provider, tools, and instructions.
    /// - Parameters:
    ///   - provider: The language model provider to use for generating responses.
    ///   - tools: An array of tools available for the agent to execute.
    ///   - instructions: System instructions for the agent.
    ///   - context: The conversation context, defaults to a new empty context.
    public init(
        provider: LanguageModelProvider,
        tools: [Tool] = [],
        instructions: String,
        context: AgentContext = .init()
    ) {
        self.provider = provider
        self.tools = tools
        self.instructions = instructions
        self.context = context
    }
    
    /// Generates a response to the given input, potentially executing tools in a loop.
    /// - Parameters:
    ///   - input: The user input to respond to.
    ///   - maxIterations: Maximum number of tool execution iterations to prevent infinite loops.
    /// - Returns: An AgentResponse containing the final content and any tool results.
    /// - Throws: AgentError.maxIterationsExceeded if the loop exceeds the limit.
    public func respond(to input: String, maxIterations: Int = 10) async throws -> AgentResponse {
        context.addMessage(.user(input))

        var toolResults: [ToolResult] = []
        var iterations = 0

        while iterations < maxIterations {
            let systemMessage = Message.system(instructions)
            let messages = [systemMessage] + context.messages
            
            let response = try await provider.generateText(
                messages: messages,
                tools: tools.map { $0.descriptor }
            )
            
            if let toolCalls = response.toolCalls {
                for call in toolCalls {
                    if let tool = tools.first(where: { $0.name == call.name }) {
                        let result = try await tool.execute(input: call.arguments)
                        toolResults.append(result)
                        context.addMessage(.tool(name: call.name, content: result.content))
                    }
                }
                iterations += 1
            } else {
                context.addMessage(.assistant(response.content))
                return AgentResponse(content: response.content, toolResults: toolResults.isEmpty ? nil : toolResults)
            }
        }
        throw AgentError.maxIterationsExceeded
    }
    

}